/* Novaris Field Kit service worker (generated by tools/make-sw.js). */
const VERSION = "5a1cb8b3ac39";
const CACHE = "nfk-" + VERSION;
const ASSETS = [
  "/field-kit/",
  "/favicon.svg",
  "/field-kit/app.css",
  "/field-kit/app.js",
  "/field-kit/diagrams.js",
  "/field-kit/export.js",
  "/field-kit/guides/event-coverage-guide.js",
  "/field-kit/guides/landscape-travel-field-guide.js",
  "/field-kit/guides/portrait-session-guide.js",
  "/field-kit/guides/product-photography-guide.js",
  "/field-kit/guides/wedding-day-guide.js",
  "/field-kit/icons/apple-touch-icon.png",
  "/field-kit/icons/icon-192.png",
  "/field-kit/icons/icon-512.png",
  "/field-kit/icons/icon-maskable-512.png",
  "/field-kit/icons/icon.svg",
  "/field-kit/index.html",
  "/field-kit/manifest.webmanifest",
  "/field-kit/store.js",
  "/field-kit/ui.js",
  "/field-kit/views/docs.js",
  "/field-kit/views/lighting.js",
  "/field-kit/views/planning.js",
  "/field-kit/views/poses.js",
  "/field-kit/views/settings.js",
  "/field-kit/views/shotlists.js",
  "/fonts/fonts.css",
  "/fonts/fraunces-latin-ext.woff2",
  "/fonts/fraunces-latin.woff2",
  "/fonts/inter-latin-ext.woff2",
  "/fonts/inter-latin.woff2",
  "/js/exposure.js",
  "/js/license-store.js",
  "/js/license.js",
  "/js/pdf.js",
  "/js/products.js",
  "/js/site-config.js",
  "/js/sun.js"
];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(ASSETS.map((url) => new Request(url, { cache: "reload" })))).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("nfk-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

function withTimeout(promise, ms) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error("timeout")), ms);
    promise.then((r) => { clearTimeout(t); resolve(r); }, (e) => { clearTimeout(t); reject(e); });
  });
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // Field Kit pages: try the network briefly, fall back to the cached app shell.
  if (req.mode === "navigate" && url.pathname.startsWith("/field-kit/")) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      try {
        const res = await withTimeout(fetch(req), 3500);
        if (res.ok) cache.put("/field-kit/", res.clone());
        return res;
      } catch {
        return (await cache.match("/field-kit/")) || (await cache.match("/field-kit/index.html")) || Response.error();
      }
    })());
    return;
  }

  // Cached files: serve from the cache straight away and refresh it in the background.
  if (ASSETS.includes(url.pathname)) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match(url.pathname);
      const network = fetch(req).then((res) => { if (res.ok) cache.put(url.pathname, res.clone()); return res; }).catch(() => null);
      if (cached) { event.waitUntil(network); return cached; }
      return (await network) || Response.error();
    })());
  }
});
